import { useState, type ChangeEvent } from 'react';
import { Button, Card, TextField } from '@jinx-ui/react';

interface RegistrationData {
  fullName: string;
  email: string;
  phone: string;
  street: string;
  city: string;
  postalCode: string;
}

interface RegistrationWizardProps {
  onSubmit: (data: RegistrationData) => void;
}

type StepId = 'contacts' | 'address' | 'review';

interface StepConfig {
  id: StepId;
  label: string;
}

const STEPS: StepConfig[] = [
  { id: 'contacts', label: 'Контакты' },
  { id: 'address', label: 'Адрес' },
  { id: 'review', label: 'Проверка' },
];

const INITIAL_DATA: RegistrationData = {
  fullName: '',
  email: '',
  phone: '',
  street: '',
  city: '',
  postalCode: '',
};

export default function RegistrationWizard({ onSubmit }: RegistrationWizardProps) {
  const [stepIndex, setStepIndex] = useState(0);
  const [formData, setFormData] = useState<RegistrationData>(INITIAL_DATA);

  const activeStep = STEPS[stepIndex];
  const isFirstStep = stepIndex === 0;
  const isLastStep = stepIndex === STEPS.length - 1;

  const handleFieldChange = (field: keyof RegistrationData) => (event: ChangeEvent<HTMLInputElement>) => {
    const { value } = event.target;
    setFormData((previous) => ({ ...previous, [field]: value }));
  };

  const handleBack = () => {
    setStepIndex((index) => Math.max(0, index - 1));
  };

  const handleNext = () => {
    setStepIndex((index) => Math.min(STEPS.length - 1, index + 1));
  };

  const handleSubmit = () => {
    onSubmit(formData);
  };

  return (
    <Card className="jx-wizard">
      <ol className="jx-wizard__steps" aria-label="Шаги регистрации">
        {STEPS.map((step, index) => {
          const status = index === stepIndex ? 'active' : index < stepIndex ? 'done' : 'upcoming';
          return (
            <li
              key={step.id}
              className={`jx-wizard__step jx-wizard__step--${status}`}
              aria-current={index === stepIndex ? 'step' : undefined}
            >
              <span className="jx-wizard__step-index">{index + 1}</span>
              <span className="jx-wizard__step-label">{step.label}</span>
            </li>
          );
        })}
      </ol>

      <div className="jx-wizard__content">
        {activeStep.id === 'contacts' && (
          <div className="jx-wizard__fields">
            <TextField
              label="Имя и фамилия"
              name="fullName"
              value={formData.fullName}
              onChange={handleFieldChange('fullName')}
              required
            />
            <TextField
              label="Email"
              name="email"
              type="email"
              value={formData.email}
              onChange={handleFieldChange('email')}
              required
            />
            <TextField
              label="Телефон"
              name="phone"
              type="tel"
              value={formData.phone}
              onChange={handleFieldChange('phone')}
              required
            />
          </div>
        )}

        {activeStep.id === 'address' && (
          <div className="jx-wizard__fields">
            <TextField
              label="Улица и дом"
              name="street"
              value={formData.street}
              onChange={handleFieldChange('street')}
              required
            />
            <TextField
              label="Город"
              name="city"
              value={formData.city}
              onChange={handleFieldChange('city')}
              required
            />
            <TextField
              label="Индекс"
              name="postalCode"
              value={formData.postalCode}
              onChange={handleFieldChange('postalCode')}
              required
            />
          </div>
        )}

        {activeStep.id === 'review' && (
          <dl className="jx-wizard__summary">
            <div className="jx-wizard__summary-row">
              <dt>Имя и фамилия</dt>
              <dd>{formData.fullName}</dd>
            </div>
            <div className="jx-wizard__summary-row">
              <dt>Email</dt>
              <dd>{formData.email}</dd>
            </div>
            <div className="jx-wizard__summary-row">
              <dt>Телефон</dt>
              <dd>{formData.phone}</dd>
            </div>
            <div className="jx-wizard__summary-row">
              <dt>Адрес</dt>
              <dd>{`${formData.street}, ${formData.city}, ${formData.postalCode}`}</dd>
            </div>
          </dl>
        )}
      </div>

      <div className="jx-wizard__footer">
        <Button type="button" variant="secondary" onClick={handleBack} disabled={isFirstStep}>
          Назад
        </Button>
        {isLastStep ? (
          <Button type="button" variant="primary" onClick={handleSubmit}>
            Отправить
          </Button>
        ) : (
          <Button type="button" variant="primary" onClick={handleNext}>
            Дальше
          </Button>
        )}
      </div>
    </Card>
  );
}

